import type { DiagramWaypoint } from '../../../services/diagrams/diagram_data'

const CORNER_RADIUS = 8

function distance(left: DiagramWaypoint, right: DiagramWaypoint) {
    return Math.hypot(right.x - left.x, right.y - left.y)
}

function pointToward(from: DiagramWaypoint, to: DiagramWaypoint, distanceFromStart: number) {
    const segmentLength = distance(from, to)
    if (segmentLength === 0) return from
    const ratio = distanceFromStart / segmentLength

    return { x: from.x + (to.x - from.x) * ratio, y: from.y + (to.y - from.y) * ratio }
}

/** Convert orthogonal waypoints to an SVG path with bounded rounded elbows. */
export function roundedDiagramPath(points: DiagramWaypoint[]) {
    if (points.length === 0) return ''
    if (points.length === 1) return `M ${points[0].x} ${points[0].y}`
    const commands = [`M ${points[0].x} ${points[0].y}`]
    for (let index = 1; index < points.length - 1; index += 1) {
        const previous = points[index - 1]
        const current = points[index]
        const next = points[index + 1]
        const radius = Math.min(CORNER_RADIUS, distance(previous, current) / 2, distance(current, next) / 2)
        const before = pointToward(current, previous, radius)
        const after = pointToward(current, next, radius)
        commands.push(`L ${before.x} ${before.y}`, `Q ${current.x} ${current.y} ${after.x} ${after.y}`)
    }
    const last = points.at(-1) as DiagramWaypoint
    commands.push(`L ${last.x} ${last.y}`)

    return commands.join(' ')
}

/** Convert two endpoints plus one derived control point to a quadratic BÃ©zier SVG path. */
export function curvedDiagramPath(points: readonly DiagramWaypoint[], controlPoint: DiagramWaypoint) {
    if (points.length !== 2) throw new Error('Curved diagram path requires exactly two endpoints')

    return `M ${points[0].x} ${points[0].y} Q ${controlPoint.x} ${controlPoint.y} ${points[1].x} ${points[1].y}`
}

import {
    useCallback, useLayoutEffect, useMemo, useRef,
    type PointerEvent as ReactPointerEvent,
    type RefObject,
} from 'react'

/** Pointer travel, in viewport pixels, above which a pan swallows its trailing click. */
export const PAN_DRAG_THRESHOLD = 3

interface DiagramSurfacePanGesture {
    moved: boolean
    pointerId: number
    pointerX: number
    pointerY: number
    scrollLeft: number
    scrollTop: number
}

export interface DiagramSurfacePanOptions {
    /** Decides whether one pointer down may start a pan; the caller owns tool and target rules. */
    canStartPan: (event: ReactPointerEvent<HTMLElement>) => boolean
    /** False drops the grab cursor, for viewports where panning is not offered right now. */
    enabled?: boolean
    onPanCancel?: () => void
    onPanComplete?: () => void
    onPanStart?: () => void
    /** True suppresses the browser's native touch scrolling while a pan runs. */
    preventDefaultForTouch?: boolean
}

export interface DiagramSurfacePan {
    beginPan: (event: ReactPointerEvent<HTMLElement>) => boolean
    cancelPan: () => boolean
    completePan: () => boolean
    /** Reads and clears the pending click suppression left by a pan that passed the drag threshold. */
    consumeSuppressedClick: () => boolean
    isPanActive: () => boolean
    updatePan: (event: ReactPointerEvent<HTMLElement>) => boolean
}

/**
 * Drags a scroll container's content with the pointer. It writes `scrollLeft` and `scrollTop` straight onto the
 * element and keeps every gesture value in refs, so a pan repaints nothing in React and no diagram coordinate or
 * zoom scale enters the calculation: the deltas are viewport pixels.
 */
export function useDiagramSurfacePan(
    scrollerRef: RefObject<HTMLElement | null>,
    {
        canStartPan,
        enabled = true,
        onPanCancel,
        onPanComplete,
        onPanStart,
        preventDefaultForTouch = false,
    }: DiagramSurfacePanOptions,
): DiagramSurfacePan {
    const gestureRef = useRef<DiagramSurfacePanGesture | null>(null)
    const suppressClickRef = useRef(false)
    const idleCursor = enabled ? 'grab' : ''

    useLayoutEffect(() => {
        const scroller = scrollerRef.current
        if (!scroller || gestureRef.current) return

        scroller.style.cursor = idleCursor
    }, [idleCursor, scrollerRef])

    const endGesture = useCallback((gesture: DiagramSurfacePanGesture) => {
        const scroller = scrollerRef.current
        gestureRef.current = null
        if (!scroller) return

        scroller.style.cursor = idleCursor
        if (scroller.hasPointerCapture?.(gesture.pointerId)) scroller.releasePointerCapture?.(gesture.pointerId)
    }, [idleCursor, scrollerRef])

    const beginPan = useCallback((event: ReactPointerEvent<HTMLElement>) => {
        const scroller = scrollerRef.current
        if (gestureRef.current || !scroller || event.button !== 0 || event.isPrimary === false) return false
        if (!canStartPan(event)) return false
        if (event.pointerType !== 'touch' || preventDefaultForTouch) event.preventDefault()

        suppressClickRef.current = false
        gestureRef.current = {
            moved: false,
            pointerId: event.pointerId,
            pointerX: event.clientX,
            pointerY: event.clientY,
            scrollLeft: scroller.scrollLeft,
            scrollTop: scroller.scrollTop,
        }
        scroller.style.cursor = 'grabbing'
        scroller.setPointerCapture?.(event.pointerId)
        onPanStart?.()

        return true
    }, [canStartPan, onPanStart, preventDefaultForTouch, scrollerRef])

    const updatePan = useCallback((event: ReactPointerEvent<HTMLElement>) => {
        const gesture = gestureRef.current
        const scroller = scrollerRef.current
        if (!gesture || gesture.pointerId !== event.pointerId || !scroller) return false

        const horizontalDelta = event.clientX - gesture.pointerX
        const verticalDelta = event.clientY - gesture.pointerY
        if (Math.abs(horizontalDelta) >= PAN_DRAG_THRESHOLD || Math.abs(verticalDelta) >= PAN_DRAG_THRESHOLD) {
            gesture.moved = true
        }
        scroller.scrollLeft = gesture.scrollLeft - horizontalDelta
        scroller.scrollTop = gesture.scrollTop - verticalDelta

        return true
    }, [scrollerRef])

    const completePan = useCallback(() => {
        const gesture = gestureRef.current
        if (!gesture) return false

        suppressClickRef.current = gesture.moved
        endGesture(gesture)
        onPanComplete?.()

        return true
    }, [endGesture, onPanComplete])

    const cancelPan = useCallback(() => {
        const gesture = gestureRef.current
        const scroller = scrollerRef.current
        if (!gesture) return false

        if (scroller) {
            scroller.scrollLeft = gesture.scrollLeft
            scroller.scrollTop = gesture.scrollTop
        }
        suppressClickRef.current = false
        endGesture(gesture)
        onPanCancel?.()

        return true
    }, [endGesture, onPanCancel, scrollerRef])

    const consumeSuppressedClick = useCallback(() => {
        const suppressed = suppressClickRef.current
        suppressClickRef.current = false

        return suppressed
    }, [])

    const isPanActive = useCallback(() => !!gestureRef.current, [])

    return useMemo(() => ({
        beginPan,
        cancelPan,
        completePan,
        consumeSuppressedClick,
        isPanActive,
        updatePan,
    }), [beginPan, cancelPan, completePan, consumeSuppressedClick, isPanActive, updatePan])
}

export interface DiagramClientPoint {
    clientX: number;
    clientY: number;
}

export interface DiagramViewportMetrics {
    bounds: {
        left: number;
        top: number;
    };
    scrollLeft: number;
    scrollTop: number;
}

export interface DiagramPoint {
    x: number;
    y: number;
}

export interface DiagramCoordinateConversion {
    diagramPoint: DiagramPoint;
    viewportPoint: DiagramPoint;
}

function requireFiniteCoordinate(value: number, name: string) {
    if (!Number.isFinite(value)) throw new Error(`${name} must be finite`);
}

/** Converts one client-space pointer through its viewport into canonical diagram coordinates. */
export function convertClientToDiagramCoordinates(
    clientPoint: DiagramClientPoint,
    viewportMetrics: DiagramViewportMetrics,
    viewportScale: number,
): DiagramCoordinateConversion {
    requireFiniteCoordinate(clientPoint.clientX, 'Client x');
    requireFiniteCoordinate(clientPoint.clientY, 'Client y');
    requireFiniteCoordinate(viewportMetrics.bounds.left, 'Viewport left');
    requireFiniteCoordinate(viewportMetrics.bounds.top, 'Viewport top');
    requireFiniteCoordinate(viewportMetrics.scrollLeft, 'Viewport scroll left');
    requireFiniteCoordinate(viewportMetrics.scrollTop, 'Viewport scroll top');
    if (!Number.isFinite(viewportScale) || viewportScale <= 0) throw new Error('Viewport scale must be positive and finite');

    const viewportPoint = {
        x: clientPoint.clientX - viewportMetrics.bounds.left + viewportMetrics.scrollLeft,
        y: clientPoint.clientY - viewportMetrics.bounds.top + viewportMetrics.scrollTop,
    };
    const diagramPoint = {
        x: viewportPoint.x / viewportScale,
        y: viewportPoint.y / viewportScale,
    };

    return { diagramPoint, viewportPoint };
}

import { useLayoutEffect, useRef, type RefObject } from 'react'

function scaledCenterOffset(offset: number, viewportSize: number, previousScale: number, scale: number) {
    return (offset + viewportSize / 2) * scale / previousScale - viewportSize / 2
}

/** Keeps viewport's visible diagram center stable across visual scale changes. */
export function usePreserveDiagramZoomCenter(scrollerRef: RefObject<HTMLElement | null>, scale: number) {
    const previousScaleRef = useRef(scale)

    useLayoutEffect(() => {
        const previousScale = previousScaleRef.current
        previousScaleRef.current = scale
        if (previousScale === scale) return

        const scroller = scrollerRef.current
        if (!scroller) return

        scroller.scrollLeft = scaledCenterOffset(scroller.scrollLeft, scroller.clientWidth, previousScale, scale)
        scroller.scrollTop = scaledCenterOffset(scroller.scrollTop, scroller.clientHeight, previousScale, scale)
    }, [scale, scrollerRef])
}

